('g2', 'kurs', 2, 'Grüße 2', 'Greetings 21–40', 'শুভেচ্ছা ২', 'phrases', 2, '<section class="rule"><h3>Say it → answer it</h3><div class="tbl"><table class="t"><tr><th>They say</th><th>You answer</th></tr>
   <tr><td lang="de">Danke!</td><td lang="de">Bitte! / Gern geschehen!</td></tr><tr><td lang="de">Entschuldigung!</td><td lang="de">Kein Problem!</td></tr>
   <tr><td lang="de">Tut mir leid.</td><td lang="de">Kein Problem!</td></tr><tr><td lang="de">Guten Appetit!</td><td lang="de">Danke, gleichfalls! (same to you)</td></tr>
   <tr><td lang="de">Schönes Wochenende!</td><td lang="de">Danke, dir auch!</td></tr></table></div>
   <p class="bnline" lang="bn">Bitte-র দুটো মানে: "অনুগ্রহ করে" এবং "আপনাকে স্বাগতম"।</p></section><section class="rule"><h3>Three wish patterns</h3><p><b lang="de">Viel ___!</b> (much ___): Viel Glück · Viel Erfolg · Viel Spaß (have fun)</p>
   <p><b lang="de">Gute ___!</b>: Gute Besserung · Gute Nacht · Gute Reise (good trip)</p>
   <p><b lang="de">Schönes / Schönen / Einen schönen ___!</b>: Schönes Wochenende · Schönen Tag noch · Einen schönen Urlaub</p>
   <p class="bnline" lang="bn">একটা কাঠামো শিখলে অনেক শুভেচ্ছা বলা যায়!</p></section>', null),
('vi', 'kurs', 3, 'Sich vorstellen', 'Introduce yourself', 'নিজের পরিচয় দেওয়া', 'phrases', 3, '<section class="rule"><h3>du or Sie?</h3><p><b>du</b> = friends, family, kids, classmates. <b>Sie</b> = teacher, boss, strangers, officials. Sie always has a capital S.</p>
   <div class="tbl"><table class="t"><tr><th>Friendly (du)</th><th>Polite (Sie)</th></tr>
   <tr><td lang="de">Wie heißt du?</td><td lang="de">Wie heißen Sie?</td></tr><tr><td lang="de">Woher kommst du?</td><td lang="de">Woher kommen Sie?</td></tr>
   <tr><td lang="de">Wie alt bist du?</td><td lang="de">Wie alt sind Sie?</td></tr></table></div>
   <p class="bnline" lang="bn">du = তুমি, Sie = আপনি। বাংলার মতোই!</p></section><section class="rule"><h3>Verb endings: -e, -st, -en</h3><p>Take the verb, cut off <b>-en</b>, add the ending for the person.</p>
   <div class="tbl"><p><b>heißen (be called)</b></p><table class="t"><tr><td>ich</td><td>heiß<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>heiß<span class="end">t</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>heiß<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>kommen (come)</b></p><table class="t"><tr><td>ich</td><td>komm<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>komm<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>komm<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>wohnen (live)</b></p><table class="t"><tr><td>ich</td><td>wohn<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>wohn<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>wohn<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>lernen (learn)</b></p><table class="t"><tr><td>ich</td><td>lern<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>lern<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>lern<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>sprechen (speak)</b></p><table class="t"><tr><td>ich</td><td>sprech<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>sprich<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>sprech<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>machen (do)</b></p><table class="t"><tr><td>ich</td><td>mach<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>mach<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>mach<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>haben (have)</b></p><table class="t"><tr><td>ich</td><td>hab<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td><b>hast</b></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td>hab<span class="end">en</span></td><td lang="bn">আপনি</td></tr></table><p><b>sein (be)</b></p><table class="t"><tr><td>ich</td><td><b>bin</b></td><td lang="bn">আমি</td></tr><tr><td>du</td><td><b>bist</b></td><td lang="bn">তুমি</td></tr><tr><td>Sie</td><td><b>sind</b></td><td lang="bn">আপনি</td></tr></table></div>
   <p class="bnline" lang="bn">বাংলাতেও ক্রিয়া বদলায়: আমি আসি, তুমি আসো, আপনি আসেন।</p></section><section class="rule"><h3>weil sends the verb to the end</h3><p>Normally the verb is in seat 2. After <b>weil</b> (because) it runs to the end:</p>
   <p lang="de">Ich lerne Deutsch, weil ich mit Leuten sprechen <span class="v2">möchte</span>.</p>
   <p class="bnline" lang="bn">বাংলার মতোই: "…কারণ আমি মানুষের সাথে কথা বলতে <b>চাই</b>" — ক্রিয়া শেষে!</p></section>', null),
('ph', 'kurs', 4, 'Phrasen', '50 common phrases', 'প্রয়োজনীয় বাক্যাংশ', 'phrases', 4, '<section class="rule"><h3>The W-question words</h3><div class="tbl"><table class="t">
   <tr><td lang="de"><b>Wie?</b></td><td>How?</td><td lang="bn">কেমন/কীভাবে?</td></tr><tr><td lang="de"><b>Was?</b></td><td>What?</td><td lang="bn">কী?</td></tr>
   <tr><td lang="de"><b>Wo?</b></td><td>Where?</td><td lang="bn">কোথায়?</td></tr><tr><td lang="de"><b>Woher?</b></td><td>From where?</td><td lang="bn">কোথা থেকে?</td></tr>
   <tr><td lang="de"><b>Wann?</b></td><td>When?</td><td lang="bn">কখন?</td></tr><tr><td lang="de"><b>Warum?</b></td><td>Why?</td><td lang="bn">কেন?</td></tr>
   <tr><td lang="de"><b>Wie viel?</b></td><td>How much?</td><td lang="bn">কত?</td></tr></table></div>
   <p class="fbtext">Trap: <b>Wo</b> = where (not who!), <b>Was</b> = what.</p></section><section class="rule"><h3>“I have hunger”, not “I am hungry”</h3><p>German uses <b>haben</b> (have) for hunger, thirst and time:</p><p lang="de">Ich <b>habe</b> Hunger. · Ich <b>habe</b> Durst. · Ich <b>habe</b> Zeit.</p>
   <p>But <b>sein</b> (be) for tired, ready, finished, age:</p><p lang="de">Ich <b>bin</b> müde. · Ich <b>bin</b> fertig. · Ich <b>bin</b> 30 Jahre alt.</p>
   <p class="bnline" lang="bn">বাংলার মতো: "আমার খিদে <b>আছে</b>" = Ich habe Hunger।</p></section><section class="rule"><h3>kein vs. nicht</h3><p><b>kein / keine</b> = “no / not any” before a thing (noun): kein Problem · keine Zeit · keine Ahnung</p>
   <p><b>nicht</b> = “not” with an action or description: Ich verstehe <b>nicht</b>. · Ich weiß <b>nicht</b>.</p>
   <p class="bnline" lang="bn">kein = কোনো … নেই, nicht = না</p></section>', null),
('s', 'kurs', 5, 'Einfache Sätze', '20 useful sentences', 'সহজ বাক্য', 'phrases', 5, '<section class="rule"><h3>The verb sits in seat 2</h3><p>In a normal sentence the verb is always the 2nd element:</p><p lang="de">Ich <span class="v2">koche</span> heute.<br>Heute <span class="v2">koche</span> ich.</p>
   <p class="bnline" lang="bn">বাংলায় ক্রিয়া শেষে থাকে (আমি আজ রান্না করছি), জার্মানে দ্বিতীয় স্থানে।</p></section><section class="rule"><h3>Nouns start with a capital</h3><p>Every German noun is capitalized: <span lang="de">Buch, Wasser, Zeit, Hund, Film, Hilfe</span>. Easy way to spot the nouns in a sentence!</p>
   <p>Each noun also has a gender: <b class="art der">der</b> Hund, <b class="art die">die</b> Zeit, <b class="art das">das</b> Buch. Learn the article with the word.</p></section>', null),
('pr', 'kurs', 6, 'Personalpronomen', 'Personal pronouns', 'ব্যক্তিবাচক সর্বনাম', 'phrases', 6, '<section class="rule"><h3>The pronoun map</h3><p>Tap a pronoun to hear it.</p>
   <div class="pmap"><span></span><span class="h">One · একবচন</span><span class="h">More · বহুবচন</span>
   <span class="h">1st</span><div class="c"><b>ich</b><span>I</span><span class="bn" lang="bn">আমি</span></div><div class="c"><b>wir</b><span>we</span><span class="bn" lang="bn">আমরা</span></div>
   <span class="h">2nd</span><div class="c"><b>du</b><span>you</span><span class="bn" lang="bn">তুমি</span></div><div class="c"><b>ihr</b><span>you all</span><span class="bn" lang="bn">তোমরা</span></div>
   <span class="h">3rd</span><div class="c"><b>er / sie / es</b><span>he / she / it</span><span class="bn" lang="bn">সে / সে / এটা</span></div><div class="c"><b>sie</b><span>they</span><span class="bn" lang="bn">তারা</span></div>
   <span class="h">Polite</span><div class="c formal"><b>Sie</b><span>you (one person or many, polite)</span><span class="bn" lang="bn">আপনি / আপনারা</span></div></div></section><section class="rule"><h3>sie, sie or Sie? Look at the verb</h3><div class="tbl"><table class="t"><tr><th>Sentence</th><th>Means</th><th>Clue</th></tr>
   <tr><td lang="de">sie <b>ist</b> nett</td><td>she is nice</td><td>verb -t / ist</td></tr>
   <tr><td lang="de">sie <b>sind</b> nett</td><td>they are nice</td><td>verb -en / sind</td></tr>
   <tr><td lang="de">Kommen <b>S</b>ie morgen?</td><td>are you (polite) coming?</td><td>capital S mid-sentence</td></tr></table></div>
   <p>At the start of a sentence “Sie sind…” can be <i>they</i> or <i>you (polite)</i>. The situation tells you.</p>
   <p class="bnline" lang="bn">ক্রিয়া দেখো: ist = সে (মেয়ে), sind = তারা বা আপনি।</p></section><section class="rule"><h3>der → er, die → sie, das → es</h3><p>Every German noun has a gender, and the pronoun follows it, even for animals and things:</p>
   <div class="tbl"><table class="t"><tr><td><b class="art der">der</b> Hund</td><td>→ <b>er</b> bellt</td><td>the dog → “he” barks</td></tr>
   <tr><td><b class="art die">die</b> Katze</td><td>→ <b>sie</b> schläft</td><td>the cat → “she” sleeps</td></tr>
   <tr><td><b class="art das">das</b> Buch</td><td>→ <b>es</b> ist alt</td><td>the book → it is old</td></tr>
   <tr><td><b class="art die">die</b> Bücher (plural)</td><td>→ <b>sie</b> sind alt</td><td>they are old</td></tr></table></div>
   <p class="bnline" lang="bn">বাংলায় "সে" সবার জন্য এক। জার্মানে শব্দের লিঙ্গ অনুযায়ী er / sie / es বদলায়।</p></section><section class="rule"><h3>Verb endings for every pronoun</h3><p>The pattern for regular verbs: <b>-e, -st, -t, -en, -t, -en</b>. sein and haben are rebels.</p>
   <div class="tbl"><p><b>gehen · যাওয়া</b></p><table class="t"><tr><td>ich</td><td>geh<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>geh<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td>geh<span class="end">t</span></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>geh<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>geh<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>geh<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>sein · হওয়া</b></p><table class="t"><tr><td>ich</td><td><b>bin</b></td><td lang="bn">আমি</td></tr><tr><td>du</td><td><b>bist</b></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td><b>ist</b></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td><b>sind</b></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td><b>seid</b></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td><b>sind</b></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>haben · থাকা</b></p><table class="t"><tr><td>ich</td><td>hab<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td><b>hast</b></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td><b>hat</b></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>hab<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>hab<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>hab<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>kommen · আসা</b></p><table class="t"><tr><td>ich</td><td>komm<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>komm<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td>komm<span class="end">t</span></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>komm<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>komm<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>komm<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>lernen · শেখা</b></p><table class="t"><tr><td>ich</td><td>lern<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>lern<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td>lern<span class="end">t</span></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>lern<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>lern<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>lern<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>sprechen · বলা</b></p><table class="t"><tr><td>ich</td><td>sprech<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>sprich<span class="end">st</span></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td>sprich<span class="end">t</span></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>sprech<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>sprech<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>sprech<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table><p><b>heißen · নাম হওয়া</b></p><table class="t"><tr><td>ich</td><td>heiß<span class="end">e</span></td><td lang="bn">আমি</td></tr><tr><td>du</td><td>heiß<span class="end">t</span></td><td lang="bn">তুমি</td></tr><tr><td>er / sie / es</td><td>heiß<span class="end">t</span></td><td lang="bn">সে / এটা</td></tr><tr><td>wir</td><td>heiß<span class="end">en</span></td><td lang="bn">আমরা</td></tr><tr><td>ihr</td><td>heiß<span class="end">t</span></td><td lang="bn">তোমরা</td></tr><tr><td>sie / Sie</td><td>heiß<span class="end">en</span></td><td lang="bn">তারা / আপনি</td></tr></table></div>
   <p class="bnline" lang="bn">বাংলাতেও একই ব্যাপার: আমি যাই, তুমি যাও, সে যায়, আপনি যান।</p></section><section class="rule"><h3>Preview: me, you, him, us…</h3><p>Your example sentences 10–20 use pronouns as the <b>object</b>. Different forms, same people:</p>
   <div class="tbl"><table class="t"><tr><th>Subject</th><th>Object (whom)</th><th>To whom</th></tr>
   <tr><td>ich</td><td>mich</td><td>mir</td></tr><tr><td>du</td><td>dich</td><td>dir</td></tr><tr><td>er</td><td>ihn</td><td>ihm</td></tr>
   <tr><td>sie</td><td>sie</td><td>ihr</td></tr><tr><td>es</td><td>es</td><td>ihm</td></tr><tr><td>wir</td><td>uns</td><td>uns</td></tr>
   <tr><td>ihr</td><td>euch</td><td>euch</td></tr><tr><td>sie / Sie</td><td>sie / Sie</td><td>ihnen / Ihnen</td></tr></table></div>
   <p class="bnline" lang="bn">আমি → আমাকে, তুমি → তোমাকে: বাংলাতেও রূপ বদলায়!</p></section>', '[{"sec":"A · Fill in the blank","q":"___ bin müde.","en":"I am tired.","bn":"আমি ক্লান্ত।","a":"ich","full":"Ich bin müde."},{"sec":"A · Fill in the blank","q":"___ hast ein Buch.","en":"You have a book.","bn":"তোমার একটা বই আছে।","a":"du","full":"Du hast ein Buch."},{"sec":"A · Fill in the blank","q":"___ ist mein Bruder.","en":"He is my brother.","bn":"সে আমার ভাই।","a":"er","full":"Er ist mein Bruder."},{"sec":"A · Fill in the blank","q":"___ ist meine Schwester.","en":"She is my sister.","bn":"সে আমার বোন।","a":"sie (she)","full":"Sie ist meine Schwester."},{"sec":"A · Fill in the blank","q":"___ ist ein Hund.","en":"It is a dog.","bn":"এটা একটা কুকুর।","a":"es","full":"Es ist ein Hund.","note":"''Es ist …'' is used to present something, even a dog. But when you talk ABOUT der Hund later, you say er."},{"sec":"A · Fill in the blank","q":"___ sind glücklich.","en":"We are happy.","bn":"আমরা খুশি।","a":"wir","full":"Wir sind glücklich."},{"sec":"A · Fill in the blank","q":"___ habt Hunger.","en":"You all are hungry.","bn":"তোমাদের খিদে পেয়েছে।","a":"ihr","full":"Ihr habt Hunger.","note":"habt is the ihr-form of haben. The -t ending gives it away."},{"sec":"A · Fill in the blank","q":"___ sind meine Freunde.","en":"They are my friends.","bn":"তারা আমার বন্ধু।","a":"sie (they)","full":"Sie sind meine Freunde."},{"sec":"A · Fill in the blank","q":"___ lernen Deutsch.","en":"You (formal) are learning German.","bn":"আপনি জার্মান শিখছেন।","a":"Sie (formal)","full":"Sie lernen Deutsch."},{"sec":"A · Fill in the blank","q":"___ komme aus Deutschland.","en":"I come from Germany.","bn":"আমি জার্মানি থেকে এসেছি।","a":"ich","full":"Ich komme aus Deutschland."},{"sec":"B · Translate to German","t":"build","en":"I am a student.","bn":"আমি একজন ছাত্র।","a":"Ich bin Student."},{"sec":"B · Translate to German","t":"build","en":"You (informal) are my friend.","bn":"তুমি আমার বন্ধু।","a":"Du bist mein Freund."},{"sec":"B · Translate to German","t":"build","en":"He is at home.","bn":"সে বাড়িতে আছে।","a":"Er ist zu Hause."},{"sec":"B · Translate to German","t":"build","en":"She is in the garden.","bn":"সে বাগানে আছে।","a":"Sie ist im Garten."},{"sec":"B · Translate to German","t":"build","en":"It is a good day.","bn":"আজ একটা ভালো দিন।","a":"Es ist ein guter Tag."},{"sec":"B · Translate to German","t":"build","en":"We are in school.","bn":"আমরা স্কুলে আছি।","a":"Wir sind in der Schule."},{"sec":"B · Translate to German","t":"build","en":"You (plural) are teachers.","bn":"তোমরা শিক্ষক।","a":"Ihr seid Lehrer."},{"sec":"B · Translate to German","t":"build","en":"They are in Berlin.","bn":"তারা বার্লিনে আছে।","a":"Sie sind in Berlin."},{"sec":"B · Translate to German","t":"build","en":"You (formal) are late.","bn":"আপনি দেরি করেছেন।","a":"Sie sind zu spät."},{"sec":"B · Translate to German","t":"build","en":"I am not sure.","bn":"আমি নিশ্চিত না।","a":"Ich bin nicht sicher."},{"sec":"C · Replace the noun","q":"Anna ist hier. → ___ ist hier.","en":"Anna is here.","bn":"আনা এখানে।","a":"sie (she)","full":"Sie ist hier."},{"sec":"C · Replace the noun","q":"Die Katze schläft. → ___ schläft.","en":"The cat is sleeping.","bn":"বিড়ালটা ঘুমাচ্ছে।","a":"sie (she)","full":"Sie schläft.","note":"Your PDF says ''It'', but in German it''s DIE Katze (feminine), so the pronoun is sie. This is Rule 3: die → sie."},{"sec":"C · Replace the noun","q":"Peter und ich spielen. → ___ spielen.","en":"Peter and I are playing.","bn":"পিটার আর আমি খেলছি।","a":"wir","full":"Wir spielen."},{"sec":"C · Replace the noun","q":"Die Kinder laufen. → ___ laufen.","en":"The children are running.","bn":"বাচ্চারা দৌড়াচ্ছে।","a":"sie (they)","full":"Sie laufen."},{"sec":"C · Replace the noun","q":"Paul liest. → ___ liest.","en":"Paul is reading.","bn":"পল পড়ছে।","a":"er","full":"Er liest."},{"sec":"C · Replace the noun","q":"(to your teacher) ___ sprechen sehr gut.","en":"You (formal) speak very well.","bn":"আপনি খুব ভালো বলেন।","a":"Sie (formal)","full":"Sie sprechen sehr gut.","note":"Talking TO a teacher, you use the polite Sie."},{"sec":"C · Replace the noun","q":"Meine Freunde und ich tanzen. → ___ tanzen.","en":"My friends and I are dancing.","bn":"আমার বন্ধুরা আর আমি নাচছি।","a":"wir","full":"Wir tanzen."},{"sec":"C · Replace the noun","q":"Die Bücher sind alt. → ___ sind alt.","en":"The books are old.","bn":"বইগুলো পুরনো।","a":"sie (they)","full":"Sie sind alt.","note":"Any plural (people or things) becomes sie."},{"sec":"C · Replace the noun","q":"Lisa und Maria essen. → ___ essen.","en":"Lisa and Maria are eating.","bn":"লিসা আর মারিয়া খাচ্ছে।","a":"sie (they)","full":"Sie essen."},{"sec":"C · Replace the noun","q":"Der Hund bellt. → ___ bellt.","en":"The dog is barking.","bn":"কুকুরটা ঘেউ ঘেউ করছে।","a":"er","full":"Er bellt.","note":"Your PDF says ''It'', but it''s DER Hund (masculine), so German says er. der → er."},{"sec":"D · Choose the correct pronoun","q":"___ bin stark.","en":"I am strong.","bn":"আমি শক্তিশালী।","opts":["ich","du"],"a":"ich","full":"Ich bin stark."},{"sec":"D · Choose the correct pronoun","q":"___ bist klug.","en":"You are smart.","bn":"তুমি বুদ্ধিমান।","opts":["ich","du"],"a":"du","full":"Du bist klug."},{"sec":"D · Choose the correct pronoun","q":"___ ist alt.","en":"He is old.","bn":"সে বয়স্ক।","opts":["er","es"],"a":"er","full":"Er ist alt."},{"sec":"D · Choose the correct pronoun","q":"___ ist klein.","en":"She is small.","bn":"সে ছোট।","opts":["sie (she)","er"],"a":"sie (she)","full":"Sie ist klein."},{"sec":"D · Choose the correct pronoun","q":"___ seid pünktlich.","en":"You all are punctual.","bn":"তোমরা সময়নিষ্ঠ।","opts":["ihr","wir"],"a":"ihr","full":"Ihr seid pünktlich."},{"sec":"D · Choose the correct pronoun","q":"___ kommen heute.","en":"We are coming today.","bn":"আমরা আজ আসছি।","opts":["wir","ihr"],"a":"wir","full":"Wir kommen heute."},{"sec":"D · Choose the correct pronoun","q":"___ spricht leise.","en":"She speaks softly.","bn":"সে আস্তে কথা বলে।","opts":["er","sie (she)"],"a":"sie (she)","full":"Sie spricht leise."},{"sec":"D · Choose the correct pronoun","q":"___ lernen schnell.","en":"They learn quickly.","bn":"তারা দ্রুত শেখে।","opts":["wir","sie (they)"],"a":"sie (they)","full":"Sie lernen schnell."},{"sec":"D · Choose the correct pronoun","q":"___ ist ein Apfel.","en":"It is an apple.","bn":"এটা একটা আপেল।","opts":["es","sie (she)"],"a":"es","full":"Es ist ein Apfel."}]'::jsonb),
