('k1l1', 0, 'In einer Kindergarten sind viele Kinder aus verschiedenen Ländern und die Gruppe ist sehr international.', 'In a kindergarten there are many children from different countries and the group is very international.', 'একটা কিন্ডারগার্টেনে বিভিন্ন দেশের অনেক শিশু আছে, আর দলটা খুবই আন্তর্জাতিক।', '', '', '', '', false),
('k1l1', 1, 'Und der Lehrer sagt: „Guten Tag!“, und alle Kinder sagen: „Guten Tag!“', 'And the teacher says: “Hello!”, and all the children say: “Hello!”', 'আর শিক্ষক বলেন: „শুভ দিন!“, আর সব শিশু বলে: „শুভ দিন!“', '', '', '', '', false),
('k1l1', 2, 'Ein Kind sagt: „Ich spreche Deutsch und Englisch.“', 'One child says: “I speak German and English.”', 'একটি শিশু বলে: „আমি জার্মান আর ইংরেজি বলি।“', '', '', '', '', false),
('k1l1', 3, 'Ein anderes Kind sagt: „Ich spreche Russisch und Türkisch.“', 'Another child says: “I speak Russian and Turkish.”', 'আরেকটি শিশু বলে: „আমি রুশ আর তুর্কি বলি।“', '', '', '', '', false),
('k1l1', 4, 'Ein weiteres Kind sagt: „Ich spreche Italienisch, Spanisch und Japanisch.“', 'Another child says: “I speak Italian, Spanish and Japanese.”', 'আরও একটি শিশু বলে: „আমি ইতালীয়, স্প্যানিশ আর জাপানি বলি।“', '', '', '', '', false),
('k1l1', 5, 'Der Lehrer fragt: „Was ist das?“, und zeigt eine Flasche.', 'The teacher asks: “What is this?” and shows a bottle.', 'শিক্ষক জিজ্ঞেস করেন: „এটা কী?“, আর একটা বোতল দেখান।', '', '', '', '', false),
('k1l1', 6, 'Ein Kind sagt: „Das ist eine Flasche.“', 'One child says: “This is a bottle.”', 'একটি শিশু বলে: „এটা একটা বোতল।“', '', '', '', '', false);
insert into public.sentences (lesson_id, idx, de, en, bn, say, emoji, tip, grp, is_list) values
('k1l1', 7, 'Dann zeigt der Lehrer ein Butterbrot und eine Nudel.', 'Then the teacher shows a butter sandwich and noodles.', 'তারপর শিক্ষক একটা মাখন-রুটি আর একটা নুডল দেখান।', '', '', '', '', false),
('k1l1', 8, 'Die Kinder sagen die Wörter in ihrer Sprache.', 'The children say the words in their own language.', 'শিশুরা শব্দগুলো নিজেদের ভাষায় বলে।', '', '', '', '', false),
('k1l1', 9, 'Ein Kind hat ein Würstchen, ein anderes Kind hat ein Würfel.', 'One child has a sausage, another child has a small sausage.', 'একটি শিশুর কাছে একটা ছোট সসেজ, আরেকটি শিশুর কাছে একটা ছক্কা (ডাইস)।', '', '', '', '', false),
('k1l1', 10, 'Der Lehrer sagt: „Bitte die Wörter zuordnen und zusammengehören.“', 'The teacher says: “Please match the words and put them together.”', 'শিক্ষক বলেন: „দয়া করে শব্দগুলো মিলিয়ে নাও, কোনগুলো একসাথে যায়।“', '', '', '', '', false),
('k1l1', 11, 'Alle Kinder arbeiten zusammen.', 'All children work together.', 'সব শিশু একসাথে কাজ করে।', '', '', '', '', false),
('k1l1', 12, 'Ein Kind ist krank, es hat ein Handtuch.', 'One child is sick and has a towel.', 'একটি শিশু অসুস্থ, তার কাছে একটা তোয়ালে আছে।', '', '', '', '', false),
('k1l1', 13, 'Alle Dinge sind in einem Koffer.', 'All things are in a suitcase.', 'সব জিনিস একটা স্যুটকেসে আছে।', '', '', '', '', false),
('k1l1', 14, 'Die Kinder fahren auf der Autobahn.', 'The children travel on the highway.', 'শিশুরা হাইওয়ে দিয়ে যাচ্ছে।', '', '', '', '', false),
('k1l1', 15, 'Am Ende sagt der Lehrer: „Guten Tag, alles ist gut.“', 'At the end the teacher says: “Hello, everything is good.”', 'শেষে শিক্ষক বলেন: „শুভ দিন, সব ঠিক আছে।“', '', '', '', '', false),
('k1l2', 0, '„Hallo im Kurs“ ist eine Situation und viele Personen sind hier.', '“Hello in the course” is a situation and many people are here.', '„Hallo im Kurs“ একটা পরিস্থিতি, আর এখানে অনেক মানুষ আছে।', '', '', '', '', false),
('k1l2', 1, 'Julia und Niklas sind bekannt.', 'Julia and Niklas are well-known.', 'জুলিয়া আর নিকলাস পরিচিত।', '', '', '', '', false),
('k1l2', 2, 'Sie sagen: „Guten Tag!“ – „Hallo, ich heiße Julia. Und du, wie heißt du?“', 'They say: “Good day!” – “Hello, my name is Julia. And you, what is your name?”', 'তারা বলে: „শুভ দিন!“ – „হ্যালো, আমার নাম জুলিয়া। আর তুমি, তোমার নাম কী?“', '', '', '', '', false),
('k1l2', 3, 'Niklas sagt: „Ich heiße Niklas. Wie geht es dir, Julia?“', 'Niklas says: “My name is Niklas. How are you, Julia?”', 'নিকলাস বলে: „আমার নাম নিকলাস। কেমন আছ, জুলিয়া?“', '', '', '', '', false),
('k1l2', 4, 'Julia sagt: „Sehr gut, danke. Und dir?“', 'Julia says: “Very good, thank you. And you?”', 'জুলিয়া বলে: „খুব ভালো, ধন্যবাদ। আর তুমি?“', '', '', '', '', false),
('k1l2', 5, 'Niklas sagt: „Auch gut, danke.“', 'Niklas says: “Also good, thank you.”', 'নিকলাস বলে: „আমিও ভালো, ধন্যবাদ।“', '', '', '', '', false),
('k1l2', 6, 'Der Lehrer sagt: „Entschuldigung, was ist das?“', 'The teacher says: “Excuse me, what is this?”', 'শিক্ষক বলেন: „মাফ করবেন, এটা কী?“', '', '', '', '', false),
('k1l2', 7, 'Julia sagt: „Das ist ein Kursplakat. Wir machen ein Plakat und sammeln Wörter. Wir kennen viele Wörter in Deutsch, Englisch, Russisch und Türkisch.“', 'Julia says: “This is a course poster. We are making a poster and collecting words. We know many words in German, English, Russian and Turkish.”', 'জুলিয়া বলে: „এটা একটা কোর্সের পোস্টার। আমরা একটা পোস্টার বানাচ্ছি আর শব্দ জোগাড় করছি। আমরা জার্মান, ইংরেজি, রুশ আর তুর্কি ভাষায় অনেক শব্দ জানি।“', '', '', '', '', false),
('k1l2', 8, 'Der Lehrer fragt: „Wer spielt hier?“', 'The teacher asks: “Who is playing here?”', 'শিক্ষক জিজ্ঞেস করেন: „এখানে কে খেলছে?“', '', '', '', '', false),
('k1l2', 9, 'Niklas spielt ein Spiel.', 'Niklas plays a game.', 'নিকলাস একটা খেলা খেলছে।', '', '', '', '', false),
('k1l2', 10, 'Julia liest ein Wort und hört Musik.', 'Julia reads a word and listens to music.', 'জুলিয়া একটা শব্দ পড়ে আর গান শোনে।', '', '', '', '', false),
('k1l2', 11, 'Sie gehen zusammen und machen die Aufgabe.', 'They go together and do the task.', 'তারা একসাথে যায় আর কাজটা করে।', '', '', '', '', false),
('k1l2', 12, 'Der Lehrer sagt: „Gut, sehr gut!“ Alle arbeiten zusammen.', 'The teacher says: “Good, very good!” Everyone works together.', 'শিক্ষক বলেন: „ভালো, খুব ভালো!“ সবাই একসাথে কাজ করে।', '', '', '', '', false),
('k1l2', 13, 'Jemand ist krank und hat ein Handtuch und eine Flasche im Koffer.', 'Someone is sick and has a towel and a bottle in the suitcase.', 'কেউ একজন অসুস্থ, আর তার স্যুটকেসে একটা তোয়ালে আর একটা বোতল আছে।', '', '', '', '', false),
('k1l2', 14, 'Der Lehrer sagt: „Bitte zuordnen die Wörter und zusammengehören.“', 'The teacher says: “Please match the words and put them together.”', 'শিক্ষক বলেন: „দয়া করে শব্দগুলো মিলিয়ে নাও, কোনগুলো একসাথে যায়।“', '', '', '', '', false),
('k1l2', 15, 'Am Ende sagt der Lehrer: „Auf Wiedersehen, bis bald, ciao!“, und alle sagen: „Tschüss!“', 'At the end the teacher says: “Goodbye, see you soon, ciao!”, and everyone says: “Bye!”', 'শেষে শিক্ষক বলেন: „আবার দেখা হবে, শীঘ্রই দেখা হবে, চাও!“, আর সবাই বলে: „বাই!“', '', '', '', '', false),
('k1l3', 0, 'Im Kurs ist ein Interview und der Lehrer sagt: „Guten Morgen!“', 'In the course there is an interview and the teacher says: “Good morning!”', 'কোর্সে একটা সাক্ষাৎকার হয়, আর শিক্ষক বলেন: „সুপ্রভাত!“', '', '', '', '', false),
('k1l3', 1, 'Und ein Herr kommt in die Klasse und sagt: „Guten Tag, Herr Hansen!“', 'And a man comes into the class and says: “Good day, Mr Hansen!”', 'আর একজন ভদ্রলোক ক্লাসে আসেন আর বলেন: „শুভ দিন, মিস্টার হানসেন!“', '', '', '', '', false),
('k1l3', 2, 'Und der Lehrer fragt: „Wie geht es Ihnen?“ Und er sagt: „Gut, danke.“', 'And the teacher asks: “How are you?” And he says: “Good, thank you.”', 'আর শিক্ষক জিজ্ঞেস করেন: „আপনি কেমন আছেন?“ আর তিনি বলেন: „ভালো, ধন্যবাদ।“', '', '', '', '', false),
('k1l3', 3, 'Der Lehrer sagt: „Wir machen ein Interview und wir notieren und wir ergänzen die Sätze.“', 'The teacher says: “We are doing an interview, and we are writing notes and completing sentences.”', 'শিক্ষক বলেন: „আমরা একটা সাক্ষাৎকার নিচ্ছি, নোট নিচ্ছি আর বাক্যগুলো পূরণ করছি।“', '', '', '', '', false),
('k1l3', 4, 'Ein Schüler sagt: „Ich komme aus Deutschland“, und ein anderer fragt: „Woher kommen Sie?“', 'A student says: “I come from Germany,” and another asks: “Where do you come from?”', 'একজন ছাত্র বলে: „আমি জার্মানি থেকে এসেছি“, আর আরেকজন জিজ্ঞেস করে: „আপনি কোথা থেকে এসেছেন?“', '', '', '', '', false),
('k1l3', 5, 'Und er sagt: „Ich komme aus Deutschland und ich wohne in Frankfurt.“', 'And he says: “I come from Germany and I live in Frankfurt.”', 'আর তিনি বলেন: „আমি জার্মানি থেকে এসেছি আর ফ্রাঙ্কফুর্টে থাকি।“', '', '', '', '', false),
('k1l3', 6, 'Der Lehrer sagt: „Das ist formell und das ist informell. Wir benutzen Personalpronomen und ein Verb.“', 'The teacher says: “This is formal and this is informal. We use personal pronouns and a verb.”', 'শিক্ষক বলেন: „এটা আনুষ্ঠানিক আর এটা অনানুষ্ঠানিক। আমরা ব্যক্তিবাচক সর্বনাম আর একটা ক্রিয়া ব্যবহার করি।“', '', '', '', '', false),
('k1l3', 7, 'Die Schüler sprechen und sagen: „Mein Vorname und mein Nachname …“', 'The students speak and say: “My first name and my last name …”', 'ছাত্রছাত্রীরা কথা বলে আর বলে: „আমার নাম আর আমার পদবি …“', '', '', '', '', false),
('k1l3', 8, 'Ein Reiseführer kommt in den Kurs und sagt: „Ich spreche Deutsch und ich arbeite als Reiseführer und ich komme aus Deutschland.“', 'A tour guide comes into the course and says: “I speak German and I work as a tour guide and I come from Germany.”', 'একজন ট্যুর গাইড কোর্সে আসেন আর বলেন: „আমি জার্মান বলি, ট্যুর গাইড হিসেবে কাজ করি আর আমি জার্মানি থেকে এসেছি।“', '', '', '', '', false),
('k1l3', 9, 'Der Lehrer sagt: „Bitte arbeitet zu zweit mit einem Partner.“', 'The teacher says: “Please work in pairs with a partner.”', 'শিক্ষক বলেন: „দয়া করে একজন সঙ্গীর সাথে জোড়ায় কাজ করো।“', '', '', '', '', false),
('k1l3', 10, 'Die Partner raten die Wörter und sie stellen sich vor.', 'The partners guess the words and they introduce themselves.', 'সঙ্গীরা শব্দগুলো অনুমান করে আর নিজেদের পরিচয় দেয়।', '', '', '', '', false),
('k1l3', 11, 'Ein Schüler fragt: „Welche Sprache sprichst du?“, und der andere sagt: „Ich spreche Englisch und Deutsch.“', 'A student asks: “Which language do you speak?” and the other says: “I speak English and German.”', 'একজন ছাত্র জিজ্ঞেস করে: „তুমি কোন ভাষা বলো?“, আর অন্যজন বলে: „আমি ইংরেজি আর জার্মান বলি।“', '', '', '', '', false),
('k1l3', 12, 'Der Lehrer sagt: „Wir üben Zahlen: acht, achtzehn und drei. Und wir lernen auch Buchstaben.“', 'The teacher says: “We practise numbers: eight, eighteen and three. And we also learn letters.”', 'শিক্ষক বলেন: „আমরা সংখ্যা অনুশীলন করি: আট, আঠারো আর তিন। আর আমরা অক্ষরও শিখি।“', '', '', '', '', false),
('k1l3', 13, 'Am Ende sagt der Lehrer: „Auf Wiedersehen und tschüss!“', 'At the end the teacher says: “Goodbye and bye!”', 'শেষে শিক্ষক বলেন: „আবার দেখা হবে, বাই!“', '', '', '', '', false),
('k1l4', 0, 'Im Kurs ist ein Gespräch und der Lehrer sagt: „Bitte schreibt eure Handynummer.“', 'In the course there is a conversation and the teacher says: “Please write your mobile phone number.”', 'কোর্সে একটা কথোপকথন হয়, আর শিক্ষক বলেন: „দয়া করে তোমাদের মোবাইল নম্বর লেখো।“', '', '', '', '', false),
('k1l4', 1, 'Und die Schüler sagen die Zahlen: eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn, elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig.', 'And the students say the numbers: one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty.', 'আর ছাত্রছাত্রীরা সংখ্যাগুলো বলে: এক, দুই, তিন, চার, পাঁচ, ছয়, সাত, আট, নয়, দশ, এগারো, বারো, তেরো, চৌদ্দ, পনেরো, ষোলো, সতেরো, আঠারো, উনিশ, বিশ।', '', '', '', '', false),
('k1l4', 2, 'Ein Schüler sagt: „Meine Zahl ist neunzehn“, und der Lehrer sagt: „Bitte laut sprechen und nicht zu leise.“', 'One student says: “My number is nineteen,” and the teacher says: “Please speak loudly and not too quietly.”', 'একজন ছাত্র বলে: „আমার সংখ্যা উনিশ“, আর শিক্ষক বলেন: „দয়া করে জোরে বলো, খুব আস্তে না।“', '', '', '', '', false),
('k1l4', 3, 'Ein anderer Schüler sagt: „Ich verstehe das nicht. Bitte noch einmal.“', 'Another student says: “I do not understand this. Please once more.”', 'আরেকজন ছাত্র বলে: „আমি এটা বুঝতে পারছি না। দয়া করে আরেকবার।“', '', '', '', '', false),
('k1l4', 4, 'Der Lehrer sagt: „Gut, wir machen das langsam.“', 'The teacher says: “Good, we will do it slowly.”', 'শিক্ষক বলেন: „ঠিক আছে, আমরা এটা ধীরে ধীরে করব।“', '', '', '', '', false),
('k1l4', 5, 'Der Lehrer fragt nach der Telefonnummer und ein Schüler sagt: „Meine Telefonnummer ist null, eins, fünf, sieben, neun, drei, zwei, acht, sechs, eins.“', 'The teacher asks for the telephone number and one student says: “My telephone number is zero, one, five, seven, nine, three, two, eight, six, one.”', 'শিক্ষক ফোন নম্বর জিজ্ঞেস করেন, আর একজন ছাত্র বলে: „আমার ফোন নম্বর শূন্য, এক, পাঁচ, সাত, নয়, তিন, দুই, আট, ছয়, এক।“', '', '', '', '', false),
('k1l4', 6, 'Der Lehrer sagt: „Bitte buchstabieren Sie auch die E-Mail-Adresse.“', 'The teacher says: “Please also spell the email address.”', 'শিক্ষক বলেন: „দয়া করে ই-মেইল ঠিকানাটাও বানান করে বলুন।“', '', '', '', '', false),
('k1l4', 7, 'Ein Schüler sagt: „Ich buchstabiere zuerst das Alphabet: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z.“', 'One student says: “I spell the alphabet first: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z.”', 'একজন ছাত্র বলে: „আমি প্রথমে বর্ণমালা বানান করি: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z।“', '', '', '', '', false),
('k1l4', 8, 'Der Lehrer sagt: „Sehr gut.“', 'The teacher says: “Very good.”', 'শিক্ষক বলেন: „খুব ভালো।“', '', '', '', '', false),
('k1l4', 9, 'Dann sagt ein Schüler: „Ich schreibe meine E-Mail-Adresse und ich sage sie laut.“', 'Then one student says: “I write my email address and I say it aloud.”', 'তারপর একজন ছাত্র বলে: „আমি আমার ই-মেইল ঠিকানা লিখি আর জোরে বলি।“', '', '', '', '', false),
('k1l4', 10, 'Ein anderer Schüler sagt: „Ich verstehe langsam besser.“', 'Another student says: “I understand better slowly.”', 'আরেকজন ছাত্র বলে: „আমি ধীরে ধীরে আরও ভালো বুঝছি।“', '', '', '', '', false),
('k1l4', 11, 'Der Lehrer sagt: „Gut, wir sprechen zusammen und wir sagen die Wörter noch einmal“, und alle arbeiten zusammen.', 'The teacher says: “Good, we speak together and we say the words again,” and everyone works together.', 'শিক্ষক বলেন: „ভালো, আমরা একসাথে বলি আর শব্দগুলো আরেকবার বলি“, আর সবাই একসাথে কাজ করে।', '', '', '', '', false),
('k1l5', 0, 'Im Kurs lernen die Schüler über Länder und Sprachen.', 'In the course, the students learn about countries and languages.', 'কোর্সে ছাত্রছাত্রীরা দেশ আর ভাষা সম্পর্কে শেখে।', '', '', '', '', false),
('k1l5', 1, 'Der Lehrer zeigt eine Tabelle und sagt: „Das ist Frankreich und die Sprache ist Französisch.“', 'The teacher shows a table and says: “This is France and the language is French.”', 'শিক্ষক একটা তালিকা দেখান আর বলেন: „এটা ফ্রান্স, আর ভাষা হলো ফরাসি।“', '', '', '', '', false),
('k1l5', 2, 'Ein Schüler sagt: „Ich lerne Spanisch.“', 'A student says: “I am learning Spanish.”', 'একজন ছাত্র বলে: „আমি স্প্যানিশ শিখছি।“', '', '', '', '', false),
('k1l5', 3, 'Ein anderer sagt: „Ich komme aus der Schweiz und ich spreche Portugiesisch.“', 'Another says: “I come from Switzerland and I speak Portuguese.”', 'আরেকজন বলে: „আমি সুইজারল্যান্ড থেকে এসেছি আর আমি পর্তুগিজ বলি।“', '', '', '', '', false),
('k1l5', 4, 'Ein anderer Schüler sagt: „Ich komme aus Japan und ich lerne Japanisch.“', 'Another student says: “I come from Japan and I am learning Japanese.”', 'আরেকজন ছাত্র বলে: „আমি জাপান থেকে এসেছি আর জাপানি শিখছি।“', '', '', '', '', false),
('k1l5', 5, 'Der Lehrer fragt: „Welche Länder kennt ihr?“', 'The teacher asks: “Which countries do you know?”', 'শিক্ষক জিজ্ঞেস করেন: „তোমরা কোন কোন দেশ চেনো?“', '', '', '', '', false),
('k1l5', 6, 'Die Schüler sagen: „Algerien, Brasilien, Österreich, Mexiko, Portugal, Thailand, Griechenland, Italien, Spanien, Russland, die Türkei und die Ukraine.“', 'The students say: “Algeria, Brazil, Austria, Mexico, Portugal, Thailand, Greece, Italy, Spain, Russia, Turkey and Ukraine.”', 'ছাত্রছাত্রীরা বলে: „আলজেরিয়া, ব্রাজিল, অস্ট্রিয়া, মেক্সিকো, পর্তুগাল, থাইল্যান্ড, গ্রিস, ইতালি, স্পেন, রাশিয়া, তুরস্ক আর ইউক্রেন।“', '', '', '', '', false),
('k1l5', 7, 'Der Lehrer sagt: „Gut, arbeitet zu zweit und bildet einen kurzen Text.“', 'The teacher says: “Good, work in pairs and write a short text.”', 'শিক্ষক বলেন: „ভালো, জোড়ায় কাজ করো আর একটা ছোট লেখা তৈরি করো।“', '', '', '', '', false),
('k1l5', 8, 'Ein Schüler sagt: „Ich komme aus Deutschland und ich wohne in einer Stadt.“', 'A student says: “I come from Germany and I live in a city.”', 'একজন ছাত্র বলে: „আমি জার্মানি থেকে এসেছি আর একটা শহরে থাকি।“', '', '', '', '', false),
('k1l5', 9, 'Ein anderer sagt: „Ich komme aus Frankreich und ich spreche Französisch.“', 'Another says: “I come from France and I speak French.”', 'আরেকজন বলে: „আমি ফ্রান্স থেকে এসেছি আর ফরাসি বলি।“', '', '', '', '', false),
('k1l5', 10, 'Der Lehrer sagt: „Bitte reagieren und benutzt die Grammatik und die W-Wörter.“', 'The teacher says: “Please react and use grammar and W-questions.”', 'শিক্ষক বলেন: „দয়া করে সাড়া দাও আর ব্যাকরণ ও W-প্রশ্নশব্দ ব্যবহার করো।“', '', '', '', '', false),
('k1l5', 11, 'Ein Schüler sagt: „Ich kenne viele Länder und ich lerne neue Sprachen.“', 'A student says: “I know many countries and I learn new languages.”', 'একজন ছাত্র বলে: „আমি অনেক দেশ চিনি আর নতুন নতুন ভাষা শিখি।“', '', '', '', '', false),
('k1l5', 12, 'Am Ende sagt der Lehrer: „Auf Wiedersehen!“, und die Schüler sagen: „Tschüss!“', 'At the end the teacher says: “Goodbye!”, and the students say: “Bye!”', 'শেষে শিক্ষক বলেন: „আবার দেখা হবে!“, আর ছাত্রছাত্রীরা বলে: „বাই!“', '', '', '', '', false),
('k1l6', 0, 'Ich habe viele Freunde und wir sind gern zusammen.', 'I have many friends and we like being together.', 'আমার অনেক বন্ধু আছে, আর আমরা একসাথে থাকতে ভালোবাসি।', '', '', '', '', false),
('k1l6', 1, 'Am Wochenende fotografieren wir und machen ein Foto.', 'On the weekend we take photos and take a picture.', 'সপ্তাহান্তে আমরা ফটোগ্রাফি করি আর ছবি তুলি।', '', '', '', '', false),
('k1l6', 2, 'Wir joggen im Park und hören Musik.', 'We jog in the park and listen to music.', 'আমরা পার্কে জগিং করি আর গান শুনি।', '', '', '', '', false),
('k1l6', 3, 'Manchmal singen wir und tanzen auch.', 'Sometimes we sing and also dance.', 'মাঝে মাঝে আমরা গান গাই আর নাচিও।', '', '', '', '', false),
('k1l6', 4, 'Wir gehen gern ins Kino und sehen einen Film.', 'We like going to the cinema and watching a film.', 'আমরা সিনেমা হলে যেতে ভালোবাসি আর একটা সিনেমা দেখি।', '', '', '', '', false),
('k1l6', 5, 'Danach kochen wir zusammen und essen Nudeln oder ein Butterbrot.', 'After that we cook together and eat noodles or a butter sandwich.', 'এরপর আমরা একসাথে রান্না করি আর নুডলস বা মাখন-রুটি খাই।', '', '', '', '', false),
('k1l6', 6, 'Ein Freund reist oft und schwimmt im See.', 'One friend travels often and swims in the lake.', 'এক বন্ধু প্রায়ই ভ্রমণ করে আর হ্রদে সাঁতার কাটে।', '', '', '', '', false),
('k1l6', 7, 'Ein anderer Freund spielt Fußball.', 'Another friend plays football.', 'আরেক বন্ধু ফুটবল খেলে।', '', '', '', '', false),
('k1l6', 8, 'Ich frage: „Gehst du gern ins Kino?“', 'I ask: “Do you like going to the cinema?”', 'আমি জিজ্ঞেস করি: „তুমি কি সিনেমা দেখতে যেতে পছন্দ করো?“', '', '', '', '', false),
('k1l6', 9, 'Er sagt: „Ja, sehr gern.“', 'He says: “Yes, very much.”', 'সে বলে: „হ্যাঁ, খুব পছন্দ করি।“', '', '', '', '', false),
('k1l6', 10, 'Ein anderer sagt: „Nein, nicht so gern.“', 'Another says: “No, not so much.”', 'আরেকজন বলে: „না, অতটা না।“', '', '', '', '', false),
('k1l6', 11, 'Wir arbeiten zu zweit und antworten auf Fragen im Kurs.', 'We work in pairs and answer questions in the course.', 'আমরা জোড়ায় কাজ করি আর কোর্সে প্রশ্নের উত্তর দিই।', '', '', '', '', false),
('k1l6', 12, 'Alles ist super und die Leute sind glücklich.', 'Everything is great and the people are happy.', 'সবকিছু দারুণ, আর মানুষজন খুশি।', '', '', '', '', false),
('k1l7', 0, 'Im Kursraum im Moment plant der Lehrer morgen ein Gespräch von wirklich dem Wochenende mit Spaghetti.', 'In the classroom at the moment the teacher is planning tomorrow a conversation about really the weekend with spaghetti.', 'এই মুহূর্তে ক্লাসরুমে শিক্ষক আগামীকালের জন্য সপ্তাহান্ত আর স্প্যাগেটি নিয়ে একটা কথোপকথনের পরিকল্পনা করছেন।', '', '', '', '', false),
('k1l7', 1, 'Wir arbeiten dritt in der Form und lernen den Infinitiv und nennen unser Hobby mit anderen.', 'We work in groups of three, learn the infinitive form and name our hobbies with others.', 'আমরা তিনজন মিলে কাজ করি, ক্রিয়ার মূল রূপ (Infinitiv) শিখি আর অন্যদের সাথে নিজেদের শখের কথা বলি।', '', '', '', '', false),
('k1l7', 2, 'Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag sind die Tage der Woche und wir lernen jeden Wochentag.', 'Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday are the days of the week and we learn every weekday.', 'সোমবার, মঙ্গলবার, বুধবার, বৃহস্পতিবার, শুক্রবার, শনিবার, রবিবার হলো সপ্তাহের দিন, আর আমরা প্রতিটি বারের নাম শিখি।', '', '', '', '', false),
('k1l7', 3, 'Wir lernen, wann die Frage ist, und gehen ins Kino.', 'We learn how to ask questions and go to the cinema.', 'আমরা শিখি কখন প্রশ্ন হয়, আর সিনেমা দেখতে যাই।', '', '', '', '', false),
('k1l7', 4, 'Leider müssen wir nachsprechen und auf die Satzmelodie achten und für oft wiederholen.', 'Unfortunately, we must repeat and pay attention to intonation and often repeat for practice.', 'দুর্ভাগ্যবশত আমাদের শুনে শুনে বলতে হয়, বাক্যের সুরের দিকে খেয়াল রাখতে হয় আর বারবার অনুশীলন করতে হয়।', '', '', '', '', false),
('k1l7', 5, 'Wir gehen durch das Café, das Museum, das Restaurant, das Schwimmbad, das Stadion, das Theater und zurück in den Kursraum.', 'We go through the café, museum, restaurant, swimming pool, stadium, theatre and back to the classroom.', 'আমরা ক্যাফে, জাদুঘর, রেস্তোরাঁ, সুইমিং পুল, স্টেডিয়াম আর থিয়েটার ঘুরে আবার ক্লাসরুমে ফিরে আসি।', '', '', '', '', false),
('k1l7', 6, 'Der Tag hat einen Termin und eine Verabredung.', 'The day has an appointment and a meeting.', 'দিনটিতে একটা অ্যাপয়েন্টমেন্ট আর একটা দেখা করার পরিকল্পনা আছে।', '', '', '', '', false),
('k1l8', 0, 'Im Kurs lernen die Schüler Zahlen und sprechen laut die Zahlen: eins, drei, vier, fünf, sechs, sieben, acht, neun, zehn, elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig, null.', 'In the class, the students learn numbers and say the numbers aloud: one, three, four, five, six, seven, eight, nine, ten, eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty, zero.', 'কোর্সে ছাত্রছাত্রীরা সংখ্যা শেখে আর জোরে জোরে সংখ্যাগুলো বলে: এক, তিন, চার, পাঁচ, ছয়, সাত, আট, নয়, দশ, এগারো, বারো, তেরো, চৌদ্দ, পনেরো, ষোলো, সতেরো, আঠারো, উনিশ, বিশ, শূন্য।', '', '', '', '', false),
('k1l8', 1, 'Ein Schüler sagt: „Meine Handynummer ist zwölf, neun, drei, sieben, fünf.“', 'One student says: “My mobile number is twelve, nine, three, seven, five.”', 'একজন ছাত্র বলে: „আমার মোবাইল নম্বর বারো, নয়, তিন, সাত, পাঁচ।“', '', '', '', '', false),
('k1l8', 2, 'Ein anderer Schüler sagt: „Ich frage nach der Telefonnummer.“', 'Another student says: “I ask for the telephone number.”', 'আরেকজন ছাত্র বলে: „আমি ফোন নম্বরটা জিজ্ঞেস করছি।“', '', '', '', '', false),
('k1l8', 3, 'Der Lehrer sagt: „Bitte sprechen Sie langsam und laut und lesen Sie das Alphabet mit.“', 'The teacher says: “Please speak slowly and loudly and read the alphabet along.”', 'শিক্ষক বলেন: „দয়া করে ধীরে আর জোরে বলুন, আর সাথে সাথে বর্ণমালা পড়ুন।“', '', '', '', '', false),
('k1l8', 4, 'Ein Schüler sagt: „Ich buchstabiere zuerst das Alphabet und schreibe die E-Mail-Adresse.“', 'One student says: “I spell the alphabet first and write the email address.”', 'একজন ছাত্র বলে: „আমি প্রথমে বর্ণমালা বানান করি, তারপর ই-মেইল ঠিকানা লিখি।“', '', '', '', '', false),
('k1l8', 5, 'Ein anderer sagt: „Ich schreibe einen Unterstrich und einen Punkt.“', 'Another says: “I write an underscore and a period.”', 'আরেকজন বলে: „আমি একটা আন্ডারস্কোর আর একটা ডট লিখি।“', '', '', '', '', false),
('k1l8', 6, 'Der Lehrer sagt: „Bitte wiederholen Sie noch einmal und achten Sie auf den Dialog.“', 'The teacher says: “Please repeat again and pay attention to the dialogue.”', 'শিক্ষক বলেন: „দয়া করে আরেকবার বলুন আর সংলাপের দিকে খেয়াল রাখুন।“', '', '', '', '', false),
('k1l8', 7, 'Ein Schüler sagt: „Ich verstehe nicht. Bitte noch einmal langsam.“', 'One student says: “I do not understand. Please again, slowly.”', 'একজন ছাত্র বলে: „আমি বুঝতে পারছি না। দয়া করে আরেকবার ধীরে বলুন।“', '', '', '', '', false),
('k1l8', 8, 'Ein anderer sagt: „Ich sage meine Nummer“, und wir sprechen zusammen.', 'Another says: “I say my number,” and we speak together.', 'আরেকজন বলে: „আমি আমার নম্বর বলছি“, আর আমরা একসাথে কথা বলি।', '', '', '', '', false),
('k1l8', 9, 'Am Ende sagt der Lehrer: „Gut, wir haben ein Gespräch und alles ist klar.“', 'At the end the teacher says: “Good, we had a conversation and everything is clear.”', 'শেষে শিক্ষক বলেন: „ভালো, আমরা একটা কথোপকথন করলাম আর সব পরিষ্কার।“', '', '', '', '', false),
('k1l9', 0, 'Das ist eine Schule in Berlin.', 'This is a school in Berlin.', 'এটা বার্লিনের একটি স্কুল।', '', '', '', '', false),
('k1l9', 1, 'Hier lernen Personen Deutsch.', 'Here, people are learning German.', 'এখানে মানুষ জার্মান শেখে।', '', '', '', '', false),
('k1l9', 2, 'Der Lehrer schreibt eine Tabelle an die Tafel.', 'The teacher writes a chart on the board.', 'শিক্ষক বোর্ডে একটি তালিকা লেখেন।', '', '', '', '', false),
('k1l9', 3, 'Er sagt: „Schreiben Sie einen kurzen Text über ein Land oder eine Stadt.“', 'He says: “Write a short text about a country or a city.”', 'তিনি বলেন: „একটি দেশ বা একটি শহর নিয়ে ছোট একটি লেখা লিখুন।“', '', '', '', '', false),
('k1l9', 4, 'Zwei Personen arbeiten zu zweit: Lucas und Elena.', 'Two people are working as a pair: Lucas and Elena.', 'দুজন মানুষ জোড়ায় কাজ করছে: লুকাস আর এলেনা।', '', '', '', '', false),
('k1l9', 5, 'Lucas kommt aus Brasilien.', 'Lucas comes from Brazil.', 'লুকাস ব্রাজিল থেকে এসেছে।', '', '', '', '', false),
('k1l9', 6, 'Er spricht Portugiesisch.', 'He speaks Portuguese.', 'সে পর্তুগিজ বলে।', '', '', '', '', false),
('k1l9', 7, 'Er sagt: „Brasilien ist ein großes Land. Und woher kommst du, Elena?“', 'He says: “Brazil is a big country. And where are you from, Elena?”', 'সে বলে: „ব্রাজিল একটি বড় দেশ। আর তুমি কোথা থেকে এসেছ, এলেনা?“', '', '', '', '', false),
('k1l9', 8, 'Elena reagiert und lächelt: „Ich komme aus der Schweiz, aber ich wohne jetzt in Österreich.', 'Elena reacts and smiles: “I come from Switzerland, but I live in Austria now.', 'এলেনা সাড়া দেয় আর হাসে: „আমি সুইজারল্যান্ড থেকে এসেছি, কিন্তু এখন অস্ট্রিয়ায় থাকি।', '', '', '', '', false),
('k1l9', 9, 'In der Schweiz spricht man Deutsch, Französisch, Italienisch und Rätoromanisch.“', 'In Switzerland, people speak German, French, Italian and Rhaeto-Romanic.”', 'সুইজারল্যান্ডে মানুষ জার্মান, ফরাসি, ইতালীয় আর রেটো-রোমান ভাষায় কথা বলে।“', '', '', '', '', false),
('k1l9', 10, 'Sie sehen andere Personen in der Klasse.', 'They see other people in the class.', 'তারা ক্লাসে অন্য মানুষদের দেখে।', '', '', '', '', false),
('k1l9', 11, 'Woher kommen sie?', 'Where are they from?', 'তারা কোথা থেকে এসেছে?', '', '', '', '', false),
('k1l9', 12, 'Olivia kommt aus den USA.', 'Olivia comes from the USA.', 'অলিভিয়া যুক্তরাষ্ট্র থেকে এসেছে।', '', '', '', '', false),
('k1l9', 13, 'Ein Mann kommt aus Polen, er spricht Polnisch.', 'A man comes from Poland, he speaks Polish.', 'একজন পুরুষ পোল্যান্ড থেকে এসেছে, সে পোলিশ বলে।', '', '', '', '', false),
('k1l9', 14, 'Zwei Frauen kommen aus Griechenland und Spanien.', 'Two women come from Greece and Spain.', 'দুজন নারী গ্রিস আর স্পেন থেকে এসেছে।', '', '', '', '', false),
('k1l9', 15, 'Eine Studentin kommt aus der Türkei.', 'A female student comes from Turkey.', 'একজন ছাত্রী তুরস্ক থেকে এসেছে।', '', '', '', '', false),
('k1l9', 16, 'Sie alle lernen die deutsche Grammatik und üben das Subjekt.', 'They all learn German grammar and practise the subject.', 'তারা সবাই জার্মান ব্যাকরণ শেখে আর কর্তা (Subjekt) অনুশীলন করে।', '', '', '', '', false),
('k1l9', 17, 'Sie lernen wichtige Redemittel und sprechen über andere Länder.', 'They learn useful phrases and speak about other countries.', 'তারা গুরুত্বপূর্ণ বাক্যাংশ শেখে আর অন্য দেশ নিয়ে কথা বলে।', '', '', '', '', false),
('k1l9', 18, 'Sie grüßen den Lehrer und am Ende verabschieden sie sich: „Tschüs! Bis morgen!“', 'They greet the teacher and at the end they say goodbye: “Bye! See you tomorrow!”', 'তারা শিক্ষককে শুভেচ্ছা জানায় আর শেষে বিদায় নেয়: „বাই! কাল দেখা হবে!“', '', '', '', '', false),
('k2l1', 0, 'Wir sind viele Leute im Deutschkurs.', 'We are many people in the German course.', 'জার্মান কোর্সে আমরা অনেক মানুষ।', '', '', '', '', false),
('k2l1', 1, 'Ich habe einen Freund, er heißt Max, und eine Freundin, sie heißt Julia.', 'I have a friend, his name is Max, and a female friend, her name is Julia.', 'আমার একজন বন্ধু আছে, তার নাম ম্যাক্স, আর একজন বান্ধবী আছে, তার নাম জুলিয়া।', '', '', '', '', false),
('k2l1', 2, 'Max ist auch mein Kollege und Julia ist meine Kollegin.', 'Max is also my colleague and Julia is my colleague.', 'ম্যাক্স আমার সহকর্মীও, আর জুলিয়া আমার সহকর্মী (নারী)।', '', '', '', '', false),
('k2l1', 3, 'Wir arbeiten zusammen, aber am Wochenende haben wir Freizeit.', 'We work together, but on the weekend we have free time.', 'আমরা একসাথে কাজ করি, কিন্তু সপ্তাহান্তে আমাদের অবসর থাকে।', '', '', '', '', false),
('k2l1', 4, 'Wir lieben Sport und Musik.', 'We love sports and music.', 'আমরা খেলাধুলা আর গান ভালোবাসি।', '', '', '', '', false),
('k2l1', 5, 'Max spielt gern Fußball und geht schwimmen.', 'Max likes to play football and goes swimming.', 'ম্যাক্স ফুটবল খেলতে পছন্দ করে আর সাঁতার কাটতে যায়।', '', '', '', '', false),
('k2l1', 6, 'Julia kann toll singen und tanzen.', 'Julia can sing and dance great.', 'জুলিয়া দারুণ গান গাইতে আর নাচতে পারে।', '', '', '', '', false),
('k2l1', 7, 'Ich reise gern und ich fotografiere.', 'I like to travel and I take photos.', 'আমি ভ্রমণ করতে ভালোবাসি আর ছবি তুলি।', '', '', '', '', false),
('k2l1', 8, 'Hier ist ein Foto: Max kocht!', 'Here is a photo: Max is cooking!', 'এই যে একটা ছবি: ম্যাক্স রান্না করছে!', '', '', '', '', false),
('k2l1', 9, 'Ich finde das sehr lustig und schreibe einen Kommentar.', 'I find that very funny and write a comment.', 'আমার কাছে এটা খুব মজার লাগে, আর আমি একটা মন্তব্য লিখি।', '', '', '', '', false),
('k2l1', 10, 'Gehen wir am Abend ins Kino?', 'Are we going to the movie theater in the evening?', 'আমরা কি সন্ধ্যায় সিনেমা দেখতে যাব?', '', '', '', '', false),
('k2l1', 11, 'Julia sagt: „Ja, super!“', 'Julia says: “Yes, super!”', 'জুলিয়া বলে: „হ্যাঁ, দারুণ!“', '', '', '', '', false),
('k2l1', 12, 'Max antwortet: „Nein, nicht so gern. Ich lese lieber ein Buch.“', 'Max answers: “No, not so much. I prefer to read a book.”', 'ম্যাক্স উত্তর দেয়: „না, অতটা পছন্দ না। আমি বরং একটা বই পড়ব।“', '', '', '', '', false),
('k2l1', 13, 'Julia fragt uns: „Joggt ihr morgen auch?“', 'Julia asks us: “Are you guys jogging tomorrow too?”', 'জুলিয়া আমাদের জিজ্ঞেস করে: „তোমরাও কি কাল জগিং করবে?“', '', '', '', '', false),
('k2l1', 14, 'Das Wochenende ist einfach toll!', 'The weekend is simply great!', 'সপ্তাহান্তটা একদম দারুণ!', '', '', '', '', false),
('k2l2', 0, 'Im Moment habe ich viel zu tun.', 'At the moment, I have a lot to do.', 'এই মুহূর্তে আমার অনেক কাজ।', '', '', '', '', false),
('k2l2', 1, 'Mein Lieblings-Hobby ist Musik, aber ich liebe auch Essen und Kultur.', 'My favorite hobby is music, but I also love food and culture.', 'আমার প্রিয় শখ গান, কিন্তু আমি খাবার আর সংস্কৃতিও ভালোবাসি।', '', '', '', '', false),
('k2l2', 2, 'Am Montag, Dienstag und Mittwoch bin ich im Kursraum.', 'On Monday, Tuesday, and Wednesday, I am in the course room.', 'সোমবার, মঙ্গলবার আর বুধবার আমি ক্লাসরুমে থাকি।', '', '', '', '', false),
('k2l2', 3, 'Aber wann habe ich Freizeit?', 'But when do I have free time?', 'কিন্তু আমার অবসর কখন?', '', '', '', '', false),
('k2l2', 4, 'Am Donnerstag habe ich eine Verabredung mit Emma.', 'On Thursday, I have an appointment with Emma.', 'বৃহস্পতিবার এমার সাথে আমার দেখা করার কথা আছে।', '', '', '', '', false),
('k2l2', 5, 'Wir gehen in ein Restaurant und essen Spaghetti.', 'We are going to a restaurant and eating spaghetti.', 'আমরা একটা রেস্তোরাঁয় যাই আর স্প্যাগেটি খাই।', '', '', '', '', false),
('k2l2', 6, 'Sie fragt mich: „Gehen wir am Freitag zusammen ins Theater?“', 'She asks me: “Are we going to the theatre together on Friday?”', 'সে আমাকে জিজ্ঞেস করে: „শুক্রবার আমরা কি একসাথে থিয়েটারে যাব?“', '', '', '', '', false),
('k2l2', 7, 'Ich antworte: „Das geht leider nicht, da habe ich einen Termin.“', 'I answer: “Unfortunately, that won''t work, I have an appointment then.”', 'আমি উত্তর দিই: „দুঃখিত, সেটা হবে না, তখন আমার একটা অ্যাপয়েন্টমেন্ট আছে।“', '', '', '', '', false),
('k2l2', 8, 'Aber am Wochenende habe ich Zeit!', 'But on the weekend, I have time!', 'কিন্তু সপ্তাহান্তে আমার সময় আছে!', '', '', '', '', false),
('k2l2', 9, 'Jeden Tag mache ich etwas Tolles.', 'Every day I do something great.', 'প্রতিদিন আমি দারুণ কিছু করি।', '', '', '', '', false),
('k2l2', 10, 'Am Samstag gehen wir durch die Stadt in ein Museum und trinken Kaffee in einem Café.', 'On Saturday, we walk through the city into a museum and drink coffee in a café.', 'শনিবার আমরা শহর ঘুরে একটা জাদুঘরে যাই আর একটা ক্যাফেতে কফি খাই।', '', '', '', '', false),
('k2l2', 11, 'Am Sonntag gehe ich ins Schwimmbad oder in ein großes Stadion.', 'On Sunday, I go to the swimming pool or to a big stadium.', 'রবিবার আমি সুইমিং পুলে বা একটা বড় স্টেডিয়ামে যাই।', '', '', '', '', false),
('k2l2', 12, 'Ein Freund fragt mich: „Gehst du wirklich morgen schon wieder zum Sport?“', 'A friend asks me: “Are you really going to sports again tomorrow?”', 'এক বন্ধু আমাকে জিজ্ঞেস করে: „তুমি কি সত্যিই কাল আবার খেলাধুলা করতে যাচ্ছ?“', '', '', '', '', false),
('k2l2', 13, 'Das ist eine gute Ja-/Nein-Frage!', 'That is a good yes/no question!', 'এটা একটা ভালো হ্যাঁ/না প্রশ্ন!', '', '', '', '', false),
('k2l3', 0, 'Jeder Mensch hat einen Beruf.', 'Every person has an occupation.', 'প্রত্যেক মানুষের একটা পেশা আছে।', '', '', '', '', false),
('k2l3', 1, 'Was machen die Personen?', 'What do the people do?', 'মানুষগুলো কী করে?', '', '', '', '', false),
('k2l3', 2, 'Sarah ist Ärztin.', 'Sarah is a doctor (f).', 'সারাহ একজন ডাক্তার (নারী)।', '', '', '', '', false),
('k2l3', 3, 'Sie hilft kranken Menschen, gibt eine Spritze oder eine Tablette und kauft ein Medikament.', 'She helps sick people, gives an injection or a pill, and buys medicine.', 'সে অসুস্থ মানুষদের সাহায্য করে, ইনজেকশন বা ট্যাবলেট দেয় আর ওষুধ কেনে।', '', '', '', '', false),
('k2l3', 4, 'Sie arbeitet viel, aber am Abend hat sie frei.', 'She works a lot, but in the evening she has time off.', 'সে অনেক কাজ করে, কিন্তু সন্ধ্যায় তার ছুটি।', '', '', '', '', false),
('k2l3', 5, 'Sie ist 30 Jahre alt.', 'She is 30 years old.', 'তার বয়স ৩০ বছর।', '', '', '', '', false),
('k2l3', 6, 'Herr Weber ist Taxifahrer.', 'Mr. Weber is a taxi driver (m).', 'মিস্টার ভেবার একজন ট্যাক্সিচালক।', '', '', '', '', false),
('k2l3', 7, 'Er hat kein eigenes Auto, aber er kann gut fahren.', 'He doesn''t have his own car, but he can drive well.', 'তার নিজের গাড়ি নেই, কিন্তু সে ভালো গাড়ি চালাতে পারে।', '', '', '', '', false),
('k2l3', 8, 'Er arbeitet bei einer großen Firma auf der Straße.', 'He works at a big company on the street.', 'সে রাস্তায় একটা বড় কোম্পানির হয়ে কাজ করে।', '', '', '', '', false),
('k2l3', 9, 'Tim ist Kellner.', 'Tim is a waiter.', 'টিম একজন ওয়েটার।', '', '', '', '', false),
('k2l3', 10, 'Er bringt ein Glas Wasser und die Rechnung für das Essen.', 'He brings a glass of water and the bill for the food.', 'সে এক গ্লাস পানি আর খাবারের বিল নিয়ে আসে।', '', '', '', '', false),
('k2l3', 11, 'Er bekommt auch etwas Geld als Trinkgeld.', 'He also gets some money as a tip.', 'সে বকশিশ হিসেবে কিছু টাকাও পায়।', '', '', '', '', false),
('k2l3', 12, 'Anna ist Studentin.', 'Anna is a student (f).', 'আনা একজন ছাত্রী।', '', '', '', '', false),
('k2l3', 13, 'Sie sitzt am Computer und lernt für ihren Kurs.', 'She sits at the computer and studies for her course.', 'সে কম্পিউটারের সামনে বসে নিজের কোর্সের জন্য পড়াশোনা করে।', '', '', '', '', false),
('k2l3', 14, 'Sie nimmt einen Stift und liest einen Artikel auf Seite 20.', 'She takes a pencil and reads an article on page 20.', 'সে একটা কলম নেয় আর ২০ পৃষ্ঠায় একটা প্রবন্ধ পড়ে।', '', '', '', '', false),
('k2l3', 15, 'Manchmal verliert sie ihren Schlüssel und muss ihn suchen.', 'Sometimes she loses her key and has to search for it.', 'মাঝে মাঝে সে তার চাবি হারিয়ে ফেলে, আর তাকে সেটা খুঁজতে হয়।', '', '', '', '', false),
('k2l3', 16, 'Es gibt viele Möglichkeiten im Leben!', 'There are many possibilities in life!', 'জীবনে অনেক সম্ভাবনা আছে!', '', '', '', '', false),
('k2l4', 0, 'Ich arbeite hier in einer Stadt.', 'I work here in a city.', 'আমি এখানে একটা শহরে কাজ করি।', '', '', '', '', false),
('k2l4', 1, 'Mein Bruder ist Krankenpfleger und seine Kollegin ist Krankenpflegerin.', 'My brother is a male nurse and his colleague is a female nurse.', 'আমার ভাই একজন নার্স, আর তার সহকর্মী একজন নার্স (নারী)।', '', '', '', '', false),
('k2l4', 2, 'Sie arbeiten in einem Krankenhaus.', 'They work in a hospital.', 'তারা একটা হাসপাতালে কাজ করে।', '', '', '', '', false),
('k2l4', 3, 'Das Krankenhaus ist sehr groß und hat Platz für viele Menschen.', 'The hospital is very large and has room for many people.', 'হাসপাতালটা অনেক বড়, আর সেখানে অনেক মানুষের জায়গা আছে।', '', '', '', '', false),
('k2l4', 4, 'Sie arbeiten von 6 Uhr bis 15 Uhr.', 'They work from 6 a.m. till 3 p.m.', 'তারা সকাল ৬টা থেকে বিকেল ৩টা পর্যন্ত কাজ করে।', '', '', '', '', false),
('k2l4', 5, 'Am Nachmittag oder nachts müssen die Menschen oft warten, denn ein Patient oder eine Patientin braucht Hilfe im Zimmer.', 'In the afternoon or at night, people often have to wait because a male patient or a female patient needs help in the room.', 'বিকেলে বা রাতে মানুষদের প্রায়ই অপেক্ষা করতে হয়, কারণ কোনো রোগীর (পুরুষ বা নারী) কক্ষে সাহায্য দরকার।', '', '', '', '', false),
('k2l4', 6, 'Mein Bruder hat meistens eine 40-Stunden-Woche.', 'My brother mostly has a 40-hour week.', 'আমার ভাইয়ের বেশিরভাগ সময় সপ্তাহে ৪০ ঘণ্টা কাজ থাকে।', '', '', '', '', false),
('k2l4', 7, 'Pro Jahr fährt er 10.000 Kilometer zur Arbeit.', 'Per year, he drives 10,000 kilometers to work.', 'বছরে সে কাজে যেতে ১০,০০০ কিলোমিটার গাড়ি চালায়।', '', '', '', '', false),
('k2l4', 8, 'Ich bin 22 Jahre alt und studiere an der Universität.', 'I am 22 years old and study at the university.', 'আমার বয়স ২২ বছর, আর আমি বিশ্ববিদ্যালয়ে পড়ি।', '', '', '', '', false),
('k2l4', 9, 'Ich habe jede Woche 24 Stunden Seminare und Kurse.', 'I have 24 hours of seminars and courses every week.', 'প্রতি সপ্তাহে আমার ২৪ ঘণ্টা সেমিনার আর কোর্স থাকে।', '', '', '', '', false),
('k2l4', 10, 'Wenn ich freihaben, lerne ich Deutsch im Kursraum.', 'When I have a holiday, I learn German in the course room.', 'যখন আমার ছুটি থাকে, আমি ক্লাসরুমে জার্মান শিখি।', '', '', '', '', false),
('k2l4', 11, 'Unser Lehrer sagt: „Wir lernen ab Seite 20. Bitte lesen Sie alle Wörter und unterstreichen Sie die Wörter hundert oder einhundert.“', 'Our teacher says: “We are learning starting at page 20. Please read all words and underline the words hundred or one hundred.”', 'আমাদের শিক্ষক বলেন: „আমরা ২০ পৃষ্ঠা থেকে শিখব। দয়া করে সব শব্দ পড়ুন আর ‘hundert’ বা ‘einhundert’ শব্দগুলোর নিচে দাগ দিন।“', '', '', '', '', false),
('k2l4', 12, 'Wir sammeln jede Information von Berufen.', 'We collect every piece of information by occupations.', 'আমরা পেশা সম্পর্কে সব তথ্য জোগাড় করি।', '', '', '', '', false),
('k2l4', 13, 'Heute müssen wir drei Berufe präsentieren: der Architekt (oder die Architektin), der Friseur (oder die Friseurin) und der Informatiker.', 'Today we have to present three occupations: the architect (m/f), the hairdresser (m/f), and the computer scientist (m).', 'আজ আমাদের তিনটি পেশা উপস্থাপন করতে হবে: স্থপতি (পুরুষ বা নারী), হেয়ারড্রেসার (পুরুষ বা নারী) আর কম্পিউটার বিজ্ঞানী।', '', '', '', '', false),
('k2l4', 14, 'Wir prüfen die Grammatik: Was ist Singular und was ist die Pluralform?', 'We check the grammar: What is singular and what is the plural form?', 'আমরা ব্যাকরণ যাচাই করি: কোনটা একবচন আর কোনটা বহুবচন রূপ?', '', '', '', '', false),
('k2l4', 15, 'Hat das Wort immer eine Pluralendung?', 'Does the word always have a plural ending?', 'শব্দটার কি সবসময় বহুবচনের প্রত্যয় থাকে?', '', '', '', '', false),
('k2l4', 16, 'Danach lernen wir gegenseitig: Wir schreiben eine Lernkarte und tauschen die Karten.', 'After that, we do mutual learning: we write a learning card and switch the cards.', 'এরপর আমরা একে অপরের কাছ থেকে শিখি: আমরা একটা লার্নিং কার্ড লিখি আর কার্ডগুলো অদলবদল করি।', '', '', '', '', false),
('k2l5', 0, 'Ein Lehrer und eine Lehrerin machen eine Umfrage im Deutschkurs.', 'A male teacher and a female teacher are doing a survey in the German course.', 'একজন শিক্ষক আর একজন শিক্ষিকা জার্মান কোর্সে একটা জরিপ করছেন।', '', '', '', '', false),
('k2l5', 1, 'Sie wollen über Berufe berichten.', 'They want to report about occupations.', 'তারা পেশা নিয়ে প্রতিবেদন করতে চান।', '', '', '', '', false),
('k2l5', 2, 'Die Lehrer sagen: „Machen Sie persönliche Angaben für unseren Club. Kennen Sie noch andere Berufe? Schreiben Sie eine Notiz.“', 'The teachers say: “Give personal information for our club. Do you know any other occupations? Write a note.”', 'শিক্ষকরা বলেন: „আমাদের ক্লাবের জন্য ব্যক্তিগত তথ্য দিন। আপনি কি আরও পেশা জানেন? একটা নোট লিখুন।“', '', '', '', '', false),
('k2l5', 3, 'Die Studenten studieren fleißig und schreiben viele Berufe auf:', 'The students study diligently and write down many occupations:', 'ছাত্রছাত্রীরা মন দিয়ে পড়ে আর অনেক পেশার নাম লিখে রাখে:', '', '', '', '', false),
('k2l5', 4, 'Eine Frau möchte Informatikerin werden.', 'A woman wants to become a female computer scientist.', 'একজন নারী কম্পিউটার বিজ্ঞানী হতে চান।', '', '', '', '', true),
('k2l5', 5, 'Ein Ingenieur und eine Ingenieurin arbeiten in einer Fabrik.', 'A male engineer and a female engineer work in a factory.', 'একজন প্রকৌশলী আর একজন নারী প্রকৌশলী একটা কারখানায় কাজ করেন।', '', '', '', '', true),
('k2l5', 6, 'Ein Verkäufer und eine Verkäuferin arbeiten im Geschäft.', 'A male salesperson and a female salesperson work in the shop.', 'একজন বিক্রেতা আর একজন নারী বিক্রেতা দোকানে কাজ করেন।', '', '', '', '', true),
('k2l5', 7, 'Ein Elektriker und eine Elektrikerin reparieren das Licht.', 'A male electrician and a female electrician repair the light.', 'একজন ইলেকট্রিশিয়ান আর একজন নারী ইলেকট্রিশিয়ান বাতি মেরামত করেন।', '', '', '', '', true),
('k2l5', 8, 'Ein Erzieher und eine Erzieherin spielen mit Kindern.', 'A male kindergarten teacher and a female kindergarten teacher play with children.', 'একজন শিশু-শিক্ষক আর একজন শিশু-শিক্ষিকা বাচ্চাদের সাথে খেলেন।', '', '', '', '', true),
('k2l5', 9, 'Ein Handwerker und eine Handwerkerin bauen ein Haus.', 'A craftsman and a craftswoman build a house.', 'একজন কারিগর আর একজন নারী কারিগর একটা বাড়ি বানান।', '', '', '', '', true),
('k2l5', 10, 'Ein Journalist und eine Journalistin schreiben für die Zeitung.', 'A male journalist and a female journalist write for the newspaper.', 'একজন সাংবাদিক আর একজন নারী সাংবাদিক পত্রিকার জন্য লেখেন।', '', '', '', '', true),
('k2l5', 11, 'Ein Jurist und eine Juristin kennen das Gesetz.', 'A male solicitor and a female solicitor know the law.', 'একজন আইনজীবী আর একজন নারী আইনজীবী আইন জানেন।', '', '', '', '', true),
('k2l5', 12, 'Ein Koch und eine Köchin machen gutes Essen.', 'A male cook and a female cook make good food.', 'একজন বাবুর্চি আর একজন নারী বাবুর্চি ভালো খাবার রান্না করেন।', '', '', '', '', true),
('k2l5', 13, 'Ein Mechaniker und eine Mechanikerin reparieren ein Auto.', 'A male mechanic and a female mechanic repair a car.', 'একজন মেকানিক আর একজন নারী মেকানিক একটা গাড়ি মেরামত করেন।', '', '', '', '', true),
('k2l5', 14, 'Ein Polizist und eine Polizistin machen die Straße sicher.', 'A male police officer and a female police officer make the street safe.', 'একজন পুলিশ আর একজন নারী পুলিশ রাস্তা নিরাপদ রাখেন।', '', '', '', '', true),
('k2l5', 15, 'Die Lehrer sagen: „Bitte machen Sie ein Beispiel und sehen Sie das Wörterbuch an. Merken Sie sich die Artikel!“', 'The teachers say: “Please give an example and look at the dictionary. Remember the articles!”', 'শিক্ষকরা বলেন: „দয়া করে একটা উদাহরণ দিন আর অভিধানটা দেখুন। আর্টিকেলগুলো মনে রাখুন!“', '', '', '', '', false),
('k2l5', 16, 'Auf einer Zeichnung sehen sie ein Artikelbild.', 'On a drawing, they see an article picture.', 'একটা আঁকা ছবিতে তারা আর্টিকেলের একটা ছবি দেখে।', '', '', '', '', false),
('k2l5', 17, 'Ein rotes Taxi steht auf der Straße.', 'A red taxi is standing on the street.', 'একটা লাল ট্যাক্সি রাস্তায় দাঁড়িয়ে আছে।', '', '', '', '', false),
('k2l5', 18, 'Wo steht die Frau?', 'Where is the woman standing?', 'মহিলাটি কোথায় দাঁড়িয়ে আছেন?', '', '', '', '', false),
('k2l5', 19, 'Sie schaut auf die Farbe.', 'She looks at the colour.', 'তিনি রঙের দিকে তাকান।', '', '', '', '', false),
('k2l5', 20, 'Um den Artikel zu lernen, nutzt jeder Student seine eigene Methode: Der Artikel der ist blau, das ist grün und die ist rot.', 'To learn the article, every student uses their own method: the article der is blue, das is green, and die is red.', 'আর্টিকেল শিখতে প্রত্যেক ছাত্র নিজের পদ্ধতি ব্যবহার করে: der নীল, das সবুজ আর die লাল।', '', '', '', '', false),
('k2l5', 21, 'Am Ende schreiben alle ihre Adresse auf.', 'At the end, everyone writes down their address.', 'শেষে সবাই তাদের ঠিকানা লিখে রাখে।', '', '', '', '', false);
