('kurs-g10', 'kurs', 'phrase', 'Hallo!', 'Hello!', 'হ্যালো!', 'HAH-loh', 'Grüße 1', '👋', 'Same as English, just say it with ''ah''.', '', 0),
('kurs-g11', 'kurs', 'phrase', 'Guten Morgen!', 'Good morning!', 'সুপ্রভাত!', 'GOO-ten MOR-gen', 'Grüße 1', '🌅', 'Morgen ≈ morning. Use it until about 11 AM.', '', 1),
('kurs-g12', 'kurs', 'phrase', 'Guten Tag!', 'Good day!', 'শুভ দিন! (দিনের বেলার শুভেচ্ছা)', 'GOO-ten TAHK', 'Grüße 1', '☀️', 'Tag ≈ day (to-DAY → TAG). The safe daytime greeting.', '', 2),
('kurs-g13', 'kurs', 'phrase', 'Guten Abend!', 'Good evening!', 'শুভ সন্ধ্যা!', 'GOO-ten AH-bent', 'Grüße 1', '🌇', 'Picture the sun going A-BEND over the horizon.', '', 3),
('kurs-g14', 'kurs', 'phrase', 'Gute Nacht!', 'Good night!', 'শুভ রাত্রি!', 'GOO-teh NAHKHT', 'Grüße 1', '🌙', 'Nacht ≈ night. Only when someone goes to sleep.', '', 4),
('kurs-g15', 'kurs', 'phrase', 'Wie geht es dir?', 'How are you?', 'তুমি কেমন আছ?', 'vee GAYT es deer', 'Grüße 1', '🙂', 'Literally ''How goes it to you?'' Short form: Wie geht''s?', '', 5),
('kurs-g16', 'kurs', 'phrase', 'Mir geht es gut.', 'I am fine.', 'আমি ভালো আছি।', 'meer gayt es GOOT', 'Grüße 1', '👍', 'gut ≈ good. ''To me it goes good.''', '', 6),
('kurs-g17', 'kurs', 'phrase', 'Und dir?', 'And you?', 'আর তুমি?', 'oont DEER', 'Grüße 1', '🫵', 'und = and. Throw the question back.', '', 7),
